import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

avg_pool_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void avg_pool1d_kernel(
    const float* input,
    float* output,
    int batch_size,
    int in_channels,
    int input_length,
    int output_length,
    int kernel_size,
    int stride,
    int padding
) {
    int index = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = batch_size * in_channels * output_length;
    if (index >= total_elements) return;

    int batch = index / (in_channels * output_length);
    int residual = index % (in_channels * output_length);
    int channel = residual / output_length;
    int out_idx = residual % output_length;

    int start = out_idx * stride - padding;
    float sum = 0.0f;

    for (int k = 0; k < kernel_size; ++k) {
        int in_pos = start + k;
        if (in_pos >= 0 && in_pos < input_length) {
            int input_offset = batch * in_channels * input_length + channel * input_length + in_pos;
            sum += input[input_offset];
        }
    }
    output[index] = sum / kernel_size;
}

torch::Tensor avg_pool1d_cuda(torch::Tensor input, int kernel_size, int stride, int padding) {
    TORCH_CHECK(input.is_cuda(), "Input must be CUDA tensor");
    TORCH_CHECK(input.dim() == 3, "Input must be 3D");

    int batch_size = input.size(0);
    int in_channels = input.size(1);
    int input_length = input.size(2);
    int output_length = ((input_length + 2*padding - kernel_size) / stride) + 1;

    auto output = torch::zeros({batch_size, in_channels, output_length}, input.options());

    int total_elements = batch_size * in_channels * output_length;
    if (total_elements == 0) return output;

    const int block_size = 256;
    int grid_size = (total_elements + block_size - 1) / block_size;

    avg_pool1d_kernel<<<grid_size, block_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        in_channels,
        input_length,
        output_length,
        kernel_size,
        stride,
        padding
    );

    return output;
}
"""

avg_pool_cpp_source = "torch::Tensor avg_pool1d_cuda(torch::Tensor input, int kernel_size, int stride, int padding);"

avg_pool = load_inline(
    name='avg_pool',
    cpp_sources=avg_pool_cpp_source,
    cuda_sources=avg_pool_source,
    functions=['avg_pool1d_cuda'],
    verbose=False
)

class ModelNew(nn.Module):
    def __init__(self, kernel_size: int, stride: int = 1, padding: int = 0):
        super().__init__()
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return avg_pool.avg_pool1d_cuda(x, self.kernel_size, self.stride, self.padding)
